<script module lang="ts">
/**
 * A Button preset that starts and stops recording (`design/components/record-button.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/record-button.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import { agentMember, agentPress, clockTime, joinSlot, watchEffect } from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/record-button.module.css'
import Button from './Button.svelte'

export interface RecordButtonProps {
  disabled?: boolean
  /**
   * The seconds the application has recorded, drawn as m:ss beside the mark while recording. It
   * is not announced, because a time read out every second interrupts everything else.
   */
  elapsed?: number
  /**
   * The Button's name while not recording: "Record a voice message".
   */
  label: string
  /**
   * The input level from 0 to 1, drawn as the size of the mark's halo while recording. It is
   * never the only sign of recording: the glyph, the frame, the name and the time say it too.
   */
  level?: number
  /**
   * The locale the time's numerals are written in; the page's own when absent.
   */
  locale?: string
  /**
   * A press while not recording: the application starts recording.
   */
  onStart?: () => void
  /**
   * A press while recording: the application stops.
   */
  onStop?: () => void
  /**
   * The application is recording. The member draws it and never sets it.
   */
  recording?: boolean
  /**
   * Button's sizes without `lg`. A record control sits beside a field, not as a page's main
   * action.
   */
  size?: 'sm' | 'md'
  /**
   * The Button's name while recording: "Stop recording".
   */
  stopLabel: string
}
</script>

<script lang="ts">
let {
  disabled = false,
  elapsed,
  label: labelOwn,
  level,
  locale,
  onStart,
  onStop,
  recording = false,
  size = 'md',
  stopLabel,
}: RecordButtonProps = $props()
const joined = joinSlot(undefined, () => ({ disabled: disabled, label: labelOwn, size: size }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
let root = $state<HTMLElement | null>(null)
const share = $derived(
  level !== undefined && Number.isFinite(level) ? Math.min(1, Math.max(0, level)) : 0,
)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'RecordButton',
    element: () => root?.querySelector('button'),
    state: () => ({ recording: recording, disabled: disabled }),
    actions: {
      stop: () =>
        (() => {
          if (!recording) throw new Error('Nothing is recording.')
          agentPress(root?.querySelector('button'))
        })(),
    },
    withholds: () => root,
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<span
    bind:this={root}
    class={styles.root}
    data-state={recording ? 'recording' : undefined}
    data-size={size}
    data-member="record-button"
    >{#if recording
      }<span class={styles.meter} data-record-button-part="meter"
        ><span class={styles.mark} style:--pm-record-button-level={share} aria-hidden="true"></span
        >{#if elapsed !== undefined
          }<span class={styles.elapsed}>{clockTime(elapsed ?? 0, locale)}</span
        >{/if
      }</span
    >{/if
    }<Button
      variant={recording ? 'outline' : 'ghost'}
      tone="neutral"
      {size}
      iconOnly={true}
      icon={recording ? 'stop' : 'record'}
      label={recording ? stopLabel : label}
      {disabled}
      onClick={() => { recording ? onStop?.() : onStart?.() }}
  /></span
>{/if
}{@render joined.end?.()}
